// Agente NUBE · flota sobre el mapa a la altura y escala que le digas.
//
// Es un agente NORMAL del framework (game.defineAgent), asi que sale en game.agents(), tiene
// a.stats/a.vars y se para con game.stopAgents(). Lo unico particular es el CUERPO, que se pide a la
// libreria: game.skills.cuerpo(a, {...}) — ver «CUERPOS DE AGENTE» en base-npc-skills.json.
//
//   game.nube()                                          // una nube con los valores de abajo
//   game.nube({ x:20, y:30, z:60, escala:5 })            // donde y de que tamano
//   game.nube({ estructura:'hab:nube', escala:2 })       // cuerpo de ESTRUCTURA (voxeles finos)
//   game.nube({ bloque:'asset:assets/white_whool.vox.json', nombre:'nube blanca' })
//   game.nube({ sombra:{ opacidad:0.7 } })               // mancha mas oscura · sombra:false la quita
//   game.agent('nube-1').stop()                          // adios
//
// DEPENDENCIA: game.skills.cuerpo vive en la libreria base (base-npc-skills.json). Si no esta
// cargada en la pagina, este snippet SE LA DESCARGA SOLO de /api/snippets/base-npc-skills y la
// ejecuta antes de crear nada. Si aun asi no aparece, NO se crea la nube (crearla sin cuerpo daria
// el cubo 1x1x1 de siempre pegado al suelo, que no es lo que has pedido).

(async function () {
  var DEF = {
    bloque:     'asset:assets/snow.vox.json',   // cuerpo por defecto: bloque de textura del atlas
    estructura: null,                            // o una clave de la galeria: 'hab:nube'
    escala:     3,                               // tamano del cuerpo en bloques (admite decimales)
    x: null, y: 26, z: null,                     // x/z nulos = delante del jugador; y = altura de la BASE
    tickMs:     900,                             // ms por celda: una nube va despacio
    sombra:     null,                            // opciones de game.skills.sombra, o false para no tenerla
    nombre:     null
  };
  var n = 0;

  // ---------------------------------------------------------------- dependencias

  function tieneCuerpo() {
    return !!(window.game && game.skills && typeof game.skills.cuerpo === 'function');
  }

  // Ejecuta un snippet del servidor tal cual lo haria el editor de scripts: ambito global y
  // AsyncFunction (la libreria usa await por dentro).
  async function ejecutarSnippet(id) {
    var r = await fetch('/api/snippets/' + id, { cache: 'no-store' });
    if (!r.ok) throw new Error('HTTP ' + r.status + ' al pedir /api/snippets/' + id);
    var d = await r.json();
    if (!d || typeof d.code !== 'string' || !d.code.trim()) throw new Error('el snippet "' + id + '" no trae codigo');
    var AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
    await (new AsyncFunction(d.code))();
  }

  async function asegurarLibreria() {
    if (tieneCuerpo()) return true;
    console.log('[nube] La libreria base de habilidades no esta cargada en esta pagina; la traigo de '
              + '/api/snippets/base-npc-skills...');
    try {
      await ejecutarSnippet('base-npc-skills');
    } catch (e) {
      console.error('[nube] No he podido cargar base-npc-skills:', e);
      return false;
    }
    if (!tieneCuerpo()) {
      console.error('[nube] base-npc-skills se ha ejecutado pero no expone game.skills.cuerpo: la version '
                  + 'guardada es anterior a la que anade los CUERPOS DE AGENTE. Actualizala y reintenta.');
      return false;
    }
    console.log('[nube] Libreria base cargada.');
    return true;
  }

  // ---------------------------------------------------------------- utilidades

  // Nombre de paleta ESTABLE derivado del asset (no del id del agente): mcAddBlock deduplica por
  // clave, asi que diez nubes del mismo bloque comparten una sola entrada en vez de diez.
  function nombreMaterial(clave) {
    var base = String(clave).split('/').pop().replace(/\.vox\.json$/, '').replace(/[^A-Za-z0-9_-]/g, '');
    return 'nube-' + (base || 'mat');
  }

  // ---------------------------------------------------------------- la nube

  game.nube = function (op) {
    if (!tieneCuerpo()) {
      console.error('[nube] Falta game.skills.cuerpo (base-npc-skills.json). Ejecuta ese snippet y luego '
                  + 'este otra vez; no creo la nube para no dejarte un cubo 1x1x1 pegado al suelo.');
      return null;
    }
    if (typeof mc === 'undefined' || !mc.grid) {
      console.error('[nube] El Mundo no esta cargado. Entra en 🌍 Mundo y vuelve a llamar a game.nube().');
      return null;
    }
    op = op || {};
    var cfg = {};
    for (var k in DEF) cfg[k] = (op[k] !== undefined && op[k] !== null) ? op[k] : DEF[k];
    if (op.estructura) cfg.bloque = null;
    var id = op.id || ('nube-' + (++n));

    var start = null;
    if (isFinite(+cfg.x) && isFinite(+cfg.z)) start = { x: Math.round(+cfg.x), z: Math.round(+cfg.z) };

    return game.defineAgent({
      id: id,
      name: cfg.nombre || 'Nube',
      goal: 'Vagar por el cielo a Y=' + cfg.y,
      block: cfg.bloque || 'stone',      // si el cuerpo es de estructura este material no se dibuja
      start: start,
      tickMs: Math.max(16, +cfg.tickMs || 900),
      margin: 1,
      passengers: false,                 // el AABB del agente es 1x1x1 aunque la nube se vea grande:
                                         // montarse encima seria enganarse. Ver LIMITACION en la libreria.
      vars: { conf: cfg },

      // onStart ASINCRONO: el framework espera a la promesa antes del primer tick, asi que el cuerpo
      // ya esta mallado (y el material descargado) cuando la nube empieza a moverse.
      onStart: async function (a) {
        var c = a.vars.conf;
        a.y = c.y - 1;                                   // cota de suelo virtual: el cuerpo va en a.y+1
        a.renderY = a.y;
        a.vars.dir = [1, 0];
        if (c.estructura) {
          await game.skills.cuerpo(a, { estructura: c.estructura, escala: c.escala, altura: c.y });
        } else {
          var mat = nombreMaterial(c.bloque);
          await game.addMaterial(c.bloque, mat);         // nombre propio: no pisa la paleta del usuario
          game.skills.cuerpo(a, { bloque: mat, escala: c.escala, altura: c.y });
        }
        // Mancha sobre el terreno: sin ella la nube flota sin peso, no se sabe donde esta.
        // Va DESPUES del cuerpo para heredarle la escala. sombra:false la quita.
        if (c.sombra !== false) game.skills.sombra(a, c.sombra || {});
        console.log('[' + id + '] nube en (' + a.x + ',' + c.y + ',' + a.z + '), escala ' + c.escala
                  + ', cuerpo ' + (c.estructura ? 'estructura ' + c.estructura : 'bloque ' + c.bloque));
      },

      // Deriva: una celda por tick en la direccion actual, rebotando en el borde del mapa y girando
      // de vez en cuando. NO usa a.walk(): walk exige suelo pisable y desnivel legal — reglas de un
      // agente que anda, no de uno que vuela. Escribir a.x/a.z directamente es lo que hace que vuele;
      // mcAgentsSmoothUpdate interpola el cuerpo entre celdas igual que a cualquier otro agente.
      onTick: function (a) {
        var d = a.vars.dir, m = a.margin;
        if (Math.random() < 0.08) {                       // un giro suelto de vez en cuando: no va en linea recta
          d = Math.random() < 0.5 ? [d[1], -d[0]] : [-d[1], d[0]];
        }
        var nx = a.x + d[0], nz = a.z + d[1];
        if (nx < m || nx >= mc.dim.x - m) { d = [-d[0], d[1]]; nx = a.x + d[0]; }
        if (nz < m || nz >= mc.dim.z - m) { d = [d[0], -d[1]]; nz = a.z + d[1]; }
        a.vars.dir = d;
        a.x = nx; a.z = nz;
        a.dir = d;
        a.stats.steps++;
        a.stats.distance++;
      },

      // Puede llegar con la libreria ya descargada de la pagina (recarga a medio vuelo): no revientes
      // el onStop del framework por eso, solo suelta el cuerpo si hay con que.
      onStop: function (a) {
        if (game.skills && typeof game.skills.liberarCuerpo === 'function') game.skills.liberarCuerpo(a);
      }
    });
  };

  // ---------------------------------------------------------------- arranque

  if (!(await asegurarLibreria())) return;               // ya se ha explicado por consola que falta
  game.nube();
  console.log('Nube creada. Mas nubes: game.nube({x:20, y:30, z:60, escala:5}) · '
            + 'cuerpo de estructura: game.nube({estructura:"hab:nube", escala:2})');
})();
